-- node_id: model.my_new_project.int_fx_rates
-- query_id: 01c6634f-080d-289e-0004-7d83412818de
-- desc: execute adapter call
create or replace   view dbt_sandbox_brice.dbt_blepoutre.int_fx_rates
  
  
  
  
  as (
    with combined as (
    select from_currency, to_currency, rate_date, rate
    from dbt_sandbox_brice.dbt_blepoutre.stg_ref_fx_rates

    union all

    select from_currency, to_currency, rate_date, rate
    from dbt_sandbox_brice.dbt_blepoutre.stg_raw_fx_rates
    where rate_date is not null
      and rate is not null
),

direct_rates as (
    select
        from_currency,
        to_currency,
        rate_date,
        rate
    from combined
    qualify row_number() over (
        partition by from_currency, to_currency, rate_date
        order by rate desc
    ) = 1
),

inverse_rates as (
    select
        to_currency as from_currency,
        from_currency as to_currency,
        rate_date,
        1.0 / nullif(rate, 0) as rate
    from direct_rates
)

select * from direct_rates
union all
select * from inverse_rates
  )
/* {"app": "dbt", "dbt_version": "2.0.0", "node_id": "model.my_new_project.int_fx_rates", "profile_name": "user", "target_name": "default"} */;
