-- node_id: model.my_new_project.int_product_master
-- query_id: 01c6634f-080d-1d04-0004-7d834127ecfa
-- desc: execute adapter call
create or replace   view dbt_sandbox_brice.dbt_blepoutre.int_product_master
  
  
  
  
  as (
    with raw_products as (
    select
        100000 + row_number() over (order by raw.sku) as product_id,
        raw.sku,
        raw.product_name,
        cat.category_id,
        sup.supplier_id,
        raw.unit_cost,
        raw.list_price,
        null as weight_g,
        'ACTIVE' as status
    from dbt_sandbox_brice.dbt_blepoutre.stg_raw_products as raw
    left join dbt_sandbox_brice.dbt_blepoutre.int_product_categories as cat
        on cat.category_name = raw.category_name
    left join dbt_sandbox_brice.dbt_blepoutre.int_suppliers as sup
        on sup.supplier_name = raw.supplier_name
    where raw.sku is not null
      and raw.sku not in (select sku from dbt_sandbox_brice.dbt_blepoutre.stg_products)
    qualify row_number() over (partition by raw.sku order by raw.row_id) = 1
)

select * from dbt_sandbox_brice.dbt_blepoutre.stg_products

union all

select * from raw_products
  )
/* {"app": "dbt", "dbt_version": "2.0.0", "node_id": "model.my_new_project.int_product_master", "profile_name": "user", "target_name": "default"} */;
