-- node_id: model.my_new_project.int_raw_orders_validated
-- query_id: 01c6634f-080d-275b-0004-7d8341282a5a
-- desc: execute adapter call
create or replace   view dbt_sandbox_brice.dbt_blepoutre.int_raw_orders_validated
  
  
  
  
  as (
    select
    raw.row_id,
    raw.external_order_ref,
    raw.customer_no,
    customer.customer_id,
    raw.order_date,
    raw.sku,
    product.product_id,
    raw.qty,
    raw.unit_price,
    raw.promo_code,
    raw.currency_code,
    raw.source_system,
    case
        when raw.customer_no is null then 'missing customer no'
        when customer.customer_id is null then 'unknown customer ' || raw.customer_no
        when product.product_id is null then 'unknown sku ' || coalesce(raw.sku, '(null)')
        when raw.qty is null or raw.qty <= 0 then 'bad qty'
    end as reject_reason
from dbt_sandbox_brice.dbt_blepoutre.stg_raw_orders as raw
left join dbt_sandbox_brice.dbt_blepoutre.int_customer_master as customer
    on customer.customer_no = raw.customer_no
    and customer.status = 'ACTIVE'
left join dbt_sandbox_brice.dbt_blepoutre.int_product_master as product
    on product.sku = raw.sku
    and product.status = 'ACTIVE'
  )
/* {"app": "dbt", "dbt_version": "2.0.0", "node_id": "model.my_new_project.int_raw_orders_validated", "profile_name": "user", "target_name": "default"} */;
