-- node_id: model.my_new_project.rpt_reorder_recommendations
-- query_id: 01c6634f-080d-1d04-0004-7d834127ed06
-- desc: execute adapter call
create or replace transient  table dbt_sandbox_brice.dbt_blepoutre.rpt_reorder_recommendations
    
    
    
    
    as (select
    stock.warehouse_id,
    product.supplier_id,
    stock.product_id,
    coalesce(stock.reorder_qty, config_values.default_reorder_qty) as recommended_order_qty,
    product.unit_cost,
    coalesce(stock.reorder_qty, config_values.default_reorder_qty) * coalesce(product.unit_cost, 0) as estimated_cost
from dbt_sandbox_brice.dbt_blepoutre.stg_stock_levels as stock
inner join dbt_sandbox_brice.dbt_blepoutre.int_product_master as product
    on product.product_id = stock.product_id
    and product.status = 'ACTIVE'
cross join dbt_sandbox_brice.dbt_blepoutre.int_config_values as config_values
where stock.qty_on_hand - stock.qty_allocated + stock.qty_on_order
    <= coalesce(stock.reorder_point, config_values.default_reorder_point)
  and product.supplier_id is not null
    )

/* {"app": "dbt", "dbt_version": "2.0.0", "node_id": "model.my_new_project.rpt_reorder_recommendations", "profile_name": "user", "target_name": "default"} */;
