-- node_id: model.my_new_project.rpt_inventory_snapshot
-- query_id: 01c6634f-080d-26f7-0004-7d834127faa2
-- desc: execute adapter call
create or replace transient  table dbt_sandbox_brice.dbt_blepoutre.rpt_inventory_snapshot
    
    
    
    
    as (select
    current_date() as snapshot_date,
    stock.warehouse_id,
    stock.product_id,
    stock.qty_on_hand,
    stock.qty_allocated,
    stock.qty_on_hand - stock.qty_allocated as qty_available,
    round(stock.qty_on_hand * coalesce(product.unit_cost, 0), 4) as stock_value,
    case
        when stock.qty_on_hand - stock.qty_allocated + stock.qty_on_order
            <= coalesce(stock.reorder_point, config_values.default_reorder_point)
            then 1
        else 0
    end as below_reorder
from dbt_sandbox_brice.dbt_blepoutre.stg_stock_levels as stock
inner join dbt_sandbox_brice.dbt_blepoutre.int_product_master as product
    on product.product_id = stock.product_id
cross join dbt_sandbox_brice.dbt_blepoutre.int_config_values as config_values
    )

/* {"app": "dbt", "dbt_version": "2.0.0", "node_id": "model.my_new_project.rpt_inventory_snapshot", "profile_name": "user", "target_name": "default"} */;
