    as (select
    snapshot.warehouse_id,
    snapshot.product_id,
    product.sku,
    product.product_name,
    supplier.supplier_name,
    snapshot.qty_available,
    stock.qty_on_order as on_order
from dbt_sandbox_brice.dbt_blepoutre.rpt_inventory_snapshot as snapshot
