-- node_id: model.my_new_project.int_order_usd_rates
-- query_id: 01c66350-080d-1d04-0004-7d834127ee5a
-- desc: execute adapter call
create or replace   view dbt_sandbox_brice.dbt_blepoutre.int_order_usd_rates
  
  
  
  
  as (
    with non_usd_rates as (
    select
        orders.order_id,
        fx.rate
    from dbt_sandbox_brice.dbt_blepoutre.fct_orders as orders
    left join dbt_sandbox_brice.dbt_blepoutre.int_fx_rates as fx
        on fx.from_currency = orders.currency_code
        and fx.to_currency = 'USD'
        and fx.rate_date <= orders.order_date
    where orders.currency_code <> 'USD'
    qualify row_number() over (
        partition by orders.order_id
        order by fx.rate_date desc nulls last
    ) = 1
)

select
    orders.order_id,
    case
        when orders.currency_code = 'USD' then 1
        else coalesce(non_usd_rates.rate, 1)
    end as usd_rate
from dbt_sandbox_brice.dbt_blepoutre.fct_orders as orders
left join non_usd_rates
    on non_usd_rates.order_id = orders.order_id
  )
/* {"app": "dbt", "dbt_version": "2.0.0", "node_id": "model.my_new_project.int_order_usd_rates", "profile_name": "user", "target_name": "default"} */;
